test.config:
common { lemmatizer_base = lemmatizer_base }
searchd {
}
source test1 { type = mysql
sql_query_pre = set names utf8 sql_query = select * from test_table sql_attr_uint = gid }
index test1 { source = test1 path = /testen1 morphology = lemmatize_en_all blend_chars = @, . wordforms = /wordforms.txt }
index test2 : test1 { path = /testen2 morphology = lemmatize_en }
index test2ruen : test2 { path = /testruen2 morphology = lemmatize_en,lemmatize_ru }
index test2red : test2 { path = /testruende2 charset_table = 0..9, A..Z, a..z, _, U+C0..U+D6, U+D9..U+DF, U+E0..U+F6, U+F9..U+FF, U+410..U+42F->U+430..U+44F, U+430..U+44F morphology = lemmatize_en,lemmatize_ru,lemmatize_de }
index testrt1 { type = rt path = /testenrt1 morphology = lemmatize_en_all blend_chars = @, . wordforms = /wordforms.txt rt_attr_uint = gid rt_field = title }
index testrt2 : testrt1 { path = /testenrt2 morphology = lemmatize_en }
index testrt2ruen : testrt2 { path = /testruenrt2 morphology = lemmatize_en,lemmatize_ru }
index testrt2red : testrt2 { path = /testred2 charset_table = 0..9, A..Z, a..z, _, U+C0..U+D6, U+D9..U+DF, U+E0..U+F6, U+F9..U+FF, U+410..U+42F->U+430..U+44F, U+430..U+44F morphology = lemmatize_en,lemmatize_ru,lemmatize_de }
index aot_plain { source = test1 path = /aot_plain morphology = lemmatize_ru_all blend_chars = . }
index aot_exact { source = test1 path = /aot_exact morphology = lemmatize_ru_all blend_chars = . index_exact_words = 1 min_prefix_len = 1 index_field_lengths = 1 morphology = stem_en, lemmatize_ru_all
}
source lem_stops { type = mysql
sql_query = select * from lem_stops sql_attr_uint = gid }
index lem_stops { source = lem_stops path = /lem_stops morphology = lemmatize_en_all stopwords = en index_exact_words = 1 }
source blend { type = mysql
sql_query_pre = set names utf8 sql_query = select * from blend_table sql_attr_uint = gid }
index aot_blend { source = blend path = /aot_blend morphology = lemmatize_en_all, lemmatize_ru_all, lemmatize_de_all min_prefix_len = 1 min_infix_len = 2 index_exact_words = 1 expand_keywords = 1 charset_table = 0..9, A..Z->a..z, _, a..z, U+00C0..U+00FF, U+410..U+42F->U+430..U+44F, U+430..U+44F, U+401->U+0435, U+451->U+0435 blend_chars = U+002D, U+002E, U+002C, +, U+0026 blend_mode = trim_tail, skip_pure }
index noaot_blend { source = blend path = /noaot_blend morphology = stem_en, stem_ru min_prefix_len = 1 min_infix_len = 2 index_exact_words = 1 expand_keywords = 1 charset_table = 0..9, A..Z->a..z, _, a..z, U+00C0..U+00FF, U+410..U+42F->U+430..U+44F, U+430..U+44F, U+401->U+0435, U+451->U+0435 blend_chars = U+002D, U+002E, U+002C, +, U+0026 blend_mode = trim_tail, skip_pure }
index aot_blend_all { source = blend path = /aot_blend_all morphology = lemmatize_en_all, lemmatize_ru_all, lemmatize_de_all min_prefix_len = 1 min_infix_len = 2 index_exact_words = 1 expand_keywords = 1 charset_table = 0..9, A..Z->a..z, _, a..z, U+00C0..U+00FF, U+410..U+42F->U+430..U+44F, U+430..U+44F, U+401->U+0435, U+451->U+0435 blend_chars = U+002D, U+002E, U+002C, +, U+0026 blend_mode = trim_all }
index noaot_blend_all { source = blend path = /noaot_blend_all morphology = stem_en, stem_ru min_prefix_len = 1 min_infix_len = 2 index_exact_words = 1 expand_keywords = 1 charset_table = 0..9, A..Z->a..z, _, a..z, U+00C0..U+00FF, U+410..U+42F->U+430..U+44F, U+430..U+44F, U+401->U+0435, U+451->U+0435 blend_chars = U+002D, U+002E, U+002C, +, U+0026 blend_mode = trim_all }
source german_source { type = mysql
sql_query_pre = set names utf8mb4 sql_query = select id, title from german_table }
index german_plain_legacy_single { source = german_source path = /german_plain_legacy_single morphology = lemmatize_de index_exact_words = 1 charset_table = non_cont, german }
index german_plain_legacy_all : german_plain_legacy_single { path = /german_plain_legacy_all morphology = lemmatize_de_all }
index german_plain_v2_single : german_plain_legacy_single { path = /german_plain_v2_single morphology = lemmatize_de_v2 }
index german_plain_v2_all : german_plain_legacy_single { path = /german_plain_v2_all morphology = lemmatize_de_v2_all }
index german_legacy_single { type = rt path = /german_legacy_single rt_field = title morphology = lemmatize_de index_exact_words = 1 charset_table = non_cont, german }
index german_legacy_all : german_legacy_single { path = /german_legacy_all morphology = lemmatize_de_all }
index german_v2_single : german_legacy_single { path = /german_v2_single morphology = lemmatize_de_v2 }
index german_v2_all : german_legacy_single { path = /german_v2_all morphology = lemmatize_de_v2_all }
index german_v2_ascii : german_legacy_single { path = /german_v2_ascii morphology = lemmatize_de_v2 charset_table = 0..9, A..Z->a..z, a..z }
index german_v2_capital : german_legacy_single { path = /german_v2_capital morphology = lemmatize_de_v2 charset_table = non_cont, U+00DF, U+1E9E }

test.db_create:
CREATE TABLE test_table
(
	id INTEGER PRIMARY KEY NOT NULL,
	gid INTEGER NOT NULL,
	title VARCHAR(255) CHARACTER SET utf8 NOT NULL
);

CREATE TABLE blend_table
(
	id INTEGER PRIMARY KEY NOT NULL,
	gid INTEGER NOT NULL,
	term VARCHAR(255) CHARACTER SET utf8 NOT NULL
);

CREATE TABLE german_table
(
	id INTEGER PRIMARY KEY NOT NULL,
	title VARCHAR(255) CHARACTER SET utf8mb4 NOT NULL
);

CREATE TABLE lem_stops
(
	id INTEGER PRIMARY KEY NOT NULL,
	gid INTEGER NOT NULL,
	title VARCHAR(255) CHARACTER SET utf8 NOT NULL
);

